package main

import (
    "log"
    "os"

    "github.com/protocol-7/config"
)

func main() {
    cfg, err := config.Load("config.toml")
    if err != nil {
        log.Fatal(err)
    }

    threshold := cfg.Threshold.Name
    if threshold > cfg.Threshold.Default {
        log.Printf("WARNING: threshold %d exceeds default %d", threshold, cfg.Threshold.Default)
    }
}
